package com.bugworld.app.garden

import com.bugworld.app.data.Species
import com.bugworld.app.interaction.HandPoint
import kotlin.math.*

/** Routes sampled from the approved GLB in stage coordinates. Time is elapsed seconds since arrival. */
object ApprovedGardenRoutes {
    private const val CONTACT_OFFSET=.003f
    private const val TAU=6.283185307f

    fun count(species: Species) = when(species) {
        Species.BUTTERFLY, Species.LADYBUG, Species.BEETLE -> 3
        else -> 2
    }
    fun seats(species: Species) = if(count(species)==2) 5 else 4

    /** InsectModel normalizes each asset's largest horizontal dimension to 0.48 m. */
    fun stageScale(species: Species)=when(species) {
        Species.BUTTERFLY, Species.CATERPILLAR -> .90f
        Species.LADYBUG -> .55f
        Species.BEETLE -> .75f
        Species.DRAGONFLY -> .65f
        Species.HONEYBEE -> .38f
        Species.ANT -> .30f
        Species.GRASSHOPPER -> .44f
    }

    // Local rest, supported crawl, stationary wing opening, airborne return.
    private data class Profile(val rest: Float,val walk: Float,val opening: Float,val flight: Float,
        val groundFraction: Float,val height: Float,val radius: Float) {
        val period=rest+walk+opening+flight
    }
    private val butterfly=Profile(1.2f,1.8f,.75f,24f,.45f,1.6f,1.10f)
    private val ladybug=Profile(1.5f,20f,1.05f,4.8f,.85f,.46f,.23f)
    private val beetle=Profile(.9f,17f,1.3f,5.8f,1f,.62f,.48f)
    private val caterpillar=Profile(0f,34f,0f,0f,1f,0f,0f)
    private val dragonfly=Profile(.45f,.62f,.22f,22f,.36f,0f,0f)
    private val honeybee=Profile(.50f,.82f,.20f,17.5f,.46f,0f,0f)
    private val ant=Profile(.45f,17.55f,0f,0f,1f,0f,0f)
    private val grasshopper=Profile(.35f,9.65f,0f,0f,1f,0f,0f)
    private fun profile(species: Species)=when(species) {
        Species.BUTTERFLY -> butterfly
        Species.LADYBUG -> ladybug
        Species.BEETLE -> beetle
        Species.CATERPILLAR -> caterpillar
        Species.DRAGONFLY -> dragonfly
        Species.HONEYBEE -> honeybee
        Species.ANT -> ant
        Species.GRASSHOPPER -> grasshopper
    }
    fun period(species: Species)=profile(species).period

    private fun path(species: Species,slot: Int): SurfacePath {
        val base=when(species) {
            Species.BUTTERFLY -> 0
            Species.LADYBUG -> 3
            Species.CATERPILLAR -> 6
            Species.BEETLE -> 8
            Species.DRAGONFLY -> 11
            Species.HONEYBEE -> 13
            Species.ANT -> 15
            Species.GRASSHOPPER -> 17
        }
        return paths[base+slot]
    }

    fun arrivalPose(species: Species,index: Int): NaturalPose =
        surfacePose(species,path(species,Math.floorMod(index,count(species))).sample(0f),false)

    fun pose(species: Species,index: Int,time: Float): NaturalPose {
        val slot=Math.floorMod(index,count(species))
        val route=path(species,slot)
        val profile=profile(species)
        val clock=if(time.isFinite()) time.coerceAtLeast(0f)%profile.period else 0f
        if(clock<profile.rest) return surfacePose(species,route.sample(0f),false)
        val walkClock=clock-profile.rest
        if(species==Species.GRASSHOPPER) return grasshopperPose(route,walkClock/profile.walk)
        if(walkClock<profile.walk || profile.flight==0f)
            return surfacePose(species,route.sample((walkClock/profile.walk)*profile.groundFraction),true)
        val from=route.sample(profile.groundFraction)
        if(walkClock<profile.walk+profile.opening)
            return surfacePose(species,from,false).copy(airborne=true)
        val f=((walkClock-profile.walk-profile.opening)/profile.flight).coerceIn(0f,1f)
        val home=route.sample(0f)
        if(species==Species.DRAGONFLY || species==Species.HONEYBEE) {
            val circuit=airCircuits[slot+if(species==Species.DRAGONFLY) 0 else 2]
            return circuit.pose(species,from,home,f)
        }
        return fly(species,from,home,profile,slot,f)
    }

    private fun surfacePose(species: Species,sample: Contact,moving: Boolean)=frame(
        species,sample.anchor,sample.normal,sample.tangent,moving,false)

    private fun fly(species: Species,from: Contact,home: Contact,profile: Profile,index: Int,f: Float): NaturalPose {
        val liftDirection=if(species==Species.BEETLE && index==2)
            (from.normal+home.normal).unit() else V(0f,1f,0f)
        val lateral=when(species) {
            // Separate outbound circuits above the three leaves.
            Species.BUTTERFLY -> when(index) {
                0 -> V(-.939693f,0f,-.342020f)
                1 -> V(.990268f,0f,.139173f)
                else -> V(1f,0f,0f)
            }
            Species.LADYBUG -> when(index) {
                0 -> V(-1f,0f,0f)
                1 -> V(0f,0f,-1f)
                else -> V(0f,0f,1f)
            }
            Species.BEETLE -> if(index==2) V(0f,0f,1f) else V(1f,0f,0f)
            else -> error("Species has its own route profile: $species")
        }
        fun position(progress: Float): V {
            val q=progress.coerceIn(0f,1f)
            val u=smooth(q)
            val base=from.anchor*(1f-u)+home.anchor*u
            if(species==Species.BUTTERFLY) {
                val edge=.05f
                val turn=when {
                    q<edge -> q*q/(2f*edge)
                    q>1-edge -> 1-edge-(1f-q)*(1f-q)/(2f*edge)
                    else -> q-edge*.5f
                }
                val angle=TAU*turn/(1-edge)
                val rise=.5f-.5f*cos(PI.toFloat()*min(1f,min(q,1f-q)*9f))
                val side=V(-lateral.z,0f,lateral.x)
                return base+lateral*((1f-cos(angle))*.62f*profile.radius)+side*(sin(angle)*profile.radius)+
                    liftDirection*(profile.height*rise)
            }
            val arch=sin(PI.toFloat()*q)
            return base+liftDirection*(profile.height*arch)+lateral*(profile.radius*arch*arch)
        }
        val mid=sin(PI.toFloat()*f)
        val up=((from.normal*(1f-f)+home.normal*f)*(1f-mid)+V(0f,1f,0f)*mid).unit()
        val velocity=position(f+.002f)-position(f-.002f)
        val horizontal=V(velocity.x,0f,velocity.z)
        val edge=(min(f,1f-f)/.10f).coerceIn(0f,1f)
        val groundHeading=if(f<.5f) from.tangent else home.tangent
        val forward=groundHeading.unit()*(1f-edge)+horizontal.unit()*edge
        return frame(species,position(f),up,forward,true,true)
    }

    /** The broad patrols and nectar visits have separate approaches and departures.
     * Stop at an intermediate waypoint to hover, with zero speed on both sides of the pause. */
    private class AirCircuit(val hover: Int,val dwell: Float,private vararg val nodes: V) {
        fun pose(species: Species,from: Contact,home: Contact,f: Float): NaturalPose {
            val legs=nodes.size+1
            val pauseStart=hover.toFloat()/legs*(1f-dwell)
            val hovering=f>=pauseStart && f<=pauseStart+dwell
            val u=when {
                f<pauseStart -> f/(1f-dwell)
                hovering -> hover.toFloat()/legs
                else -> (f-dwell)/(1f-dwell)
            }
            fun node(i: Int)=when(i) { 0 -> from.anchor; legs -> home.anchor; else -> nodes[i-1] }
            fun tangent(i: Int)=if(i==0 || i==legs || i==hover) V(0f,0f,0f) else (node(i+1)-node(i-1))*.5f
            fun point(q: Float): V {
                val progress=q.coerceIn(0f,1f)*legs
                val i=progress.toInt().coerceAtMost(legs-1)
                return cubic(node(i),node(i+1),tangent(i),tangent(i+1),progress-i)
            }
            val velocity=point(u+.005f)-point(u-.005f)
            val blend=(min(f,1f-f)/.09f).coerceIn(0f,1f)
            val contact=if(f<.5f) from else home
            val normal=(contact.normal*(1f-blend)+V(0f,1f,0f)*blend).unit()
            val direction=contact.tangent.unit()*(1f-blend)+velocity.unit()*blend
            return frame(species,point(u),normal,direction,!hovering,true)
        }
    }

    private val airCircuits=listOf(
        AirCircuit(3,.045f,
            V(.58f,.96f,-3.47f),V(.29f,1.17f,-3.69f),V(-.69f,1.25f,-3.72f),
            V(-.71f,1.02f,-2.86f),V(.46f,1.45f,-2.30f),V(.26f,.95f,-2.73f)),
        AirCircuit(3,.045f,
            V(-.74f,.84f,1.53f),V(-1.07f,1.10f,1.26f),V(-1.66f,1.03f,1.23f),
            V(-1.54f,.85f,2.17f),V(-1.02f,.93f,2.54f),V(-.56f,1.12f,2.52f)),
        AirCircuit(6,.04f,
            V(-.75f,1.20f,-1.68f),V(-1.05f,1.15f,-1.32f),V(-.84f,1.05f,-.95f),
            V(-.32f,.88f,-.96f),V(-.11f,.79f,-1.45f),V(-.12f,.78f,-1.88f)),
        AirCircuit(4,.04f,
            V(2.84f,1.31f,.67f),V(3.60f,1.00f,.34f),V(3.21f,1.03f,-1.33f),
            V(2.90f,.81f,-2.23f),V(2.52f,.97f,-1.81f),V(1.87f,1.17f,-.69f),
            V(2.41f,1.24f,-.03f)),
    )

    private fun cubic(a: V,b: V,ta: V,tb: V,q: Float): V {
        val q2=q*q; val q3=q2*q
        return a*(2f*q3-3f*q2+1f)+ta*(q3-2f*q2+q)+b*(3f*q2-2f*q3)+tb*(q3-q2)
    }

    /** Two leg-powered arcs and a final wing-assisted return. Every endpoint is an actual support. */
    private fun grasshopperPose(route: SurfacePath,fraction: Float): NaturalPose {
        val f=fraction.coerceIn(0f,1f)
        val start: Float; val end: Float; val height: Float; val jump: Boolean
        when(f) {
            in .18f.. .32f -> { start=.18f; end=.32f; height=.13f; jump=true }
            in .50f.. .64f -> { start=.50f; end=.64f; height=.16f; jump=true }
            in .83f..1f -> { start=.83f; end=1f; height=.24f; jump=false }
            else -> return surfacePose(Species.GRASSHOPPER,route.sample(f),true)
        }
        val q=((f-start)/(end-start)).coerceIn(0f,1f)
        val a=route.sample(start); val b=route.sample(end)
        val delta=b.anchor-a.anchor
        val length=sqrt(delta.dot(delta))
        val rise=4f*q*(1f-q)
        val point=cubic(a.anchor,b.anchor,a.tangent.unit()*length,b.tangent.unit()*length,q)+V(0f,height*rise,0f)
        val normal=((a.normal*(1f-q)+b.normal*q)*(1f-rise)+V(0f,1f,0f)*rise).unit()
        val direction=(a.tangent.unit()*(1f-q)+b.tangent.unit()*q).unit()
        return frame(Species.GRASSHOPPER,point,normal,direction,true,true).copy(hopPhase=if(jump) q else null)
    }

    /** The SDK uses Ry(yaw) Rx(pitch) Rz(roll). Butterfly's native front is -Z; the others are +X. */
    private fun frame(species: Species,point: V,normal: V,direction: V,moving: Boolean,airborne: Boolean): NaturalPose {
        val up=normal.unit()
        val forward=direction.onPlane(up).unit()
        val x: V; val z: V
        if(species==Species.BUTTERFLY) { z=forward*-1f; x=up.cross(z).unit() }
        else { x=forward; z=x.cross(up).unit() }
        val toDegrees=180f/PI.toFloat()
        val pitch=asin((-z.y).coerceIn(-1f,1f))*toDegrees
        val yaw=atan2(z.x,z.z)*toDegrees
        val roll=atan2(x.y,up.y)*toDegrees
        return NaturalPose(HandPoint(point.x,point.y,point.z),yaw,pitch,moving,roll,airborne)
    }

    private fun smooth(value: Float) = value*value*(3f-2f*value)
    private data class V(val x: Float,val y: Float,val z: Float) {
        operator fun plus(other: V)=V(x+other.x,y+other.y,z+other.z)
        operator fun minus(other: V)=V(x-other.x,y-other.y,z-other.z)
        operator fun times(scale: Float)=V(x*scale,y*scale,z*scale)
        fun dot(other: V)=x*other.x+y*other.y+z*other.z
        fun cross(other: V)=V(y*other.z-z*other.y,z*other.x-x*other.z,x*other.y-y*other.x)
        fun unit(): V { val length=sqrt(dot(this)); return if(length>1e-7f) this*(1f/length) else V(1f,0f,0f) }
        fun onPlane(normal: V)=this-normal*dot(normal)
    }
    private data class Contact(val point: V,val normal: V,val tangent: V) {
        val anchor get()=point+normal*CONTACT_OFFSET
    }
    private class SurfacePath(private val points: FloatArray, private val closed: Boolean) {
        private val last=points.size/6-1
        private val distances=FloatArray(last+1).apply {
            for(i in 1..last) {
                val a=(i-1)*6;val b=i*6
                this[i]=this[i-1]+sqrt((points[b]-points[a]).pow(2)+(points[b+1]-points[a+1]).pow(2)+(points[b+2]-points[a+2]).pow(2))
            }
        }
        fun sample(progress: Float): Contact {
            val distance=progress.coerceIn(0f,1f)*distances.last()
            val found=distances.binarySearch(distance)
            val index=(if(found>=0) found else -found-2).coerceIn(0,last-1)
            val blend=(distance-distances[index])/(distances[index+1]-distances[index]).coerceAtLeast(1e-7f)
            fun vector(i: Int,normal: Boolean=false): V {
                val offset=i*6+if(normal) 3 else 0
                return V(points[offset],points[offset+1],points[offset+2])
            }
            val a=vector(index); val b=vector(index+1)
            val normal=(vector(index,true)*(1f-blend)+vector(index+1,true)*blend).unit()
            fun knot(i: Int)=vector(if(closed) Math.floorMod(i,last) else i.coerceIn(0,last))
            val tangent=(knot(index+3)-knot(index-3))*(1f-blend)+(knot(index+4)-knot(index-2))*blend
            return Contact(a*(1f-blend)+b*blend,normal,tangent)
        }
    }
